(2) \begin{cases}x^{2}+y^{2}=4\\y=kx+1\end{cases} \Rightarrow x^{2}+(kx+1)^{2}=4

(k^{2}+1)x^{2}+2kx-3=0

\therefore x_{1}+x_{2}=\frac{-2k}{k^{2}+1},\quad x_{1}x_{2}=\frac{-3}{k^{2}+1}

\overrightarrow{OP}\cdot\overrightarrow{OQ}=x_{1}x_{2}+y_{1}y_{2}=\frac{-3}{k^{2}+1}+y_{1}y_{2}

y_{1}y_{2}=k^{2}x_{1}x_{2}+k(x_{1}+x_{2})+1=\frac{-4k^{2}+1}{k^{2}+1}

\overrightarrow{OP}\cdot\overrightarrow{OQ}=\frac{-4k^{2}-2}{k^{2}+1}=-2

(1) k_{1}=-\frac{1}{k}

\therefore l_{1}:\; y-1=-\frac{1}{k}x

\frac{1}{k}x+y-1=0

\begin{cases}x^{2}+y^{2}=4\\\frac{1}{k}x+y-1=0\end{cases} \Rightarrow \left(1+\frac{1}{k^{2}}\right)x^{2}-\frac{2}{k}x-3=0

